pub fn is_palindrome(text: Vec<char>) -> bool {
    // ASCII-only lowercase mapping: 'A'..'Z' -> 'a'..'z', everything else unchanged.
    fn to_ascii_lower(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            // Safe because the mapped value stays within ASCII.
            ((c as u8) + (b'a' - b'A')) as char
        } else {
            c
        }
    }

    let n = text.len();
    for i in 0..(n / 2) {
        if to_ascii_lower(text[i]) != to_ascii_lower(text[n - 1 - i]) {
            return false;
        }
    }
    true
}